import hashlib,json,os,re,statistics,subprocess,tempfile,time
from pathlib import Path
os.sched_setaffinity(0,{0})
binaries={'parent':'build/review-j01-final/release/mus-solver','candidate':'build/review-j01-preload/release/mus-solver'}
data={'method':'Three paired alternating runs, CPU0, seed7, one thread. Compare unchanged workloads against eb6bd55. Public prior is a new optional feature with no prior implementation; report its absolute cost separately.','binary_sha256':{k:hashlib.sha256(Path(v).read_bytes()).hexdigest() for k,v in binaries.items()},'runs':[],'summary':[]}
out=Path('/tmp/mus-review-j01-preload-performance.json')
def save():out.write_text(json.dumps(data,indent=2)+'\n')
def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def run(group,version,args,repeat):
 command=[binaries[version],*args]
 with tempfile.TemporaryFile(mode='w+') as log:
  start=time.perf_counter();pid=os.posix_spawn(command[0],command,os.environ,file_actions=[(os.POSIX_SPAWN_DUP2,log.fileno(),1),(os.POSIX_SPAWN_DUP2,log.fileno(),2)])
  _,status,usage=os.wait4(pid,0);elapsed=time.perf_counter()-start;log.seek(0);stdout=log.read()
 if status:raise RuntimeError((command,status,stdout))
 row={'group':group,'version':version,'repeat':repeat,'command':command,'wall_seconds':elapsed,'peak_rss_kib':usage.ru_maxrss,'stdout':stdout}
 data['runs'].append(row);save();print(group,version,repeat,elapsed,usage.ru_maxrss,flush=True)
 return row
def summarize(group,paired=True):
 rows=[r for r in data['runs'] if r['group']==group];s={'group':group}
 for metric in ['wall_seconds','peak_rss_kib']:
  b=statistics.median(r[metric] for r in rows if r['version']=='candidate');s[metric]={'candidate':b}
  if paired:
   a=statistics.median(r[metric] for r in rows if r['version']=='parent');s[metric].update(parent=a,change_percent=100*(b/a-1))
 data['summary'].append(s);save();print('SUMMARY',json.dumps(s),flush=True)
 if paired and (s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25):raise RuntimeError('Performance gate requires five confirmation pairs')
with tempfile.TemporaryDirectory(prefix='mus-review-j01-preload-bench-') as tmp:
 base=Path(tmp)
 for fmt in ['ordago','ordago-public']:
  source=base/(fmt+'.cfr')
  subprocess.run([binaries['parent'],'--format',fmt,'--iterations','20','--seed','7','--save',str(source)],stdout=subprocess.DEVNULL,check=True)
  data.setdefault('sources',{})[fmt]={'iterations':20,'seed':7,'sha256':digest(source),'bytes':source.stat().st_size}
 reference=None
 for repeat in range(3):
  for version in (['parent','candidate'] if repeat%2==0 else ['candidate','parent']):
   row=run('ordago-public',version,['--format','ordago-public','--iterations','500','--seed','7'],repeat+1)
   counters={k:int(v) for k,v in re.findall(r'(visited_nodes|information_sets|iterations)=([0-9]+)',row['stdout'])}
   if reference is None:reference=counters
   assert counters==reference
   row['counters_identical']=True;save()
 summarize('ordago-public')
 for group,prior in [('score',None),('score-legacy-prior','ordago'),('score-public-prior','ordago-public')]:
  reference=None
  for repeat in range(3):
   versions=['candidate'] if group=='score-public-prior' else (['parent','candidate'] if repeat%2==0 else ['candidate','parent'])
   for version in versions:
    directory=base/f'{group}-{version}-{repeat}'
    args=['--format','ordago-score','--score','35:35','--continuation',str(directory),'--iterations','1000','--evaluation-samples','10000','--seed','7','--threads','1']
    if prior:args+=['--preload-ordago',str(base/(prior+'.cfr'))]
    row=run(group,version,args,repeat+1)
    hashes={p.name:digest(p) for p in sorted(directory.iterdir()) if p.is_file()}
    assert len(hashes)==46
    if reference is None:reference=hashes
    assert hashes==reference,(group,version,repeat)
    row['file_sha256']=hashes;row['files_identical']=True;save()
  summarize(group,group!='score-public-prior')
 for fmt,source in data['sources'].items():assert digest(base/(fmt+'.cfr'))==source['sha256']
 data['sources_preserved']=True;save()
print('ALL_CHECKS_PASSED',flush=True)
